import importlib.util
import json
import subprocess
import tempfile
import unittest
from pathlib import Path

SCRIPT = Path(__file__).parent / 'staging/entire-continuity/scripts/classify_evidence.py'
spec = importlib.util.spec_from_file_location('classifier', SCRIPT)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)

class EvidenceTests(unittest.TestCase):
    def evidence(self, **changes):
        e = dict(applicable=True, enabled=True, hooks_discovered=True,
                 hooks_trusted=True, fresh_lifecycle=True, resolution='caller-env',
                 caller_id='fixture-session', session_id='fixture-session',
                 worktree='/isolated/fixture', expected_worktree='/isolated/fixture',
                 source='live', state='active', checkpoint_id='fixture-checkpoint',
                 checkpoint_session='fixture-session', commit='a'*40,
                 checkpoint_commit='a'*40, local_sha='b'*40, remote_sha='b'*40,
                 usage=12, dirty=False, diverged=False)
        e.update(changes)
        return e

    def test_live_and_synced(self):
        r = module.classify(self.evidence())
        self.assertTrue(r['live_capture'].startswith('verified'))
        self.assertTrue(r['remote_sync'].startswith('matching'))
        self.assertEqual(r['dashboard_ingestion'], 'separate observation required')

    def test_discovery_only(self):
        for changes in ({'fresh_lifecycle':False}, {'hooks_trusted':False},
                        {'session_id':None}, {'state':'ended'}, {'source':'unknown'}):
            self.assertEqual(module.classify(self.evidence(**changes))['live_capture'], 'unverified')

    def test_wrong_caller_and_worktree(self):
        for changes in ({'resolution':'other-worktree'}, {'session_id':'someone-else'},
                        {'worktree':'/other'}):
            self.assertEqual(module.classify(self.evidence(**changes))['live_capture'], 'unverified')

    def test_historical_not_live(self):
        r = module.classify(self.evidence(source='historical'))
        self.assertEqual(r['live_capture'], 'unverified')
        self.assertEqual(r['history'], 'historical')

    def test_local_only_and_mismatch(self):
        for remote in (None, 'c'*40):
            r = module.classify(self.evidence(remote_sha=remote))
            self.assertTrue(r['local_linkage'].startswith('verified'))
            self.assertEqual(r['remote_sync'], 'unverified')

    def test_missing_usage_and_explicit_zero(self):
        for usage in (None, -1, True, '0'):
            self.assertEqual(module.classify(self.evidence(usage=usage))['usage'], 'unavailable')
        self.assertEqual(module.classify(self.evidence(usage=0))['usage'], 0)

    def test_dirty_diverged_does_not_trigger_repair(self):
        r = module.classify(self.evidence(dirty=True, diverged=True))
        self.assertEqual(r['checkout'], {'dirty':True, 'diverged':True})
        self.assertTrue(r['live_capture'].startswith('verified'))

    def test_unrelated_excluded(self):
        self.assertEqual(module.classify(self.evidence(applicable=False)),
                         {'scope':'excluded', 'live_capture':'not evaluated'})

    def test_commit_identity_and_checkpoint_continuity(self):
        for changes in ({'checkpoint_commit':'c'*40}, {'checkpoint_session':'other'},
                        {'local_sha':None}, {'local_sha':'short', 'remote_sha':'short'}):
            r = module.classify(self.evidence(**changes))
            self.assertEqual(r['local_linkage'], 'unverified')
            self.assertEqual(r['remote_sync'], 'unverified')

    def test_cli_is_read_only_and_bounded(self):
        with tempfile.TemporaryDirectory() as d:
            f = Path(d)/'evidence.json'
            for value, code in ((json.dumps(self.evidence()), 0), ('secret invalid', 2),
                                ('x'*16385, 2), ('[]', 2)):
                f.write_text(value)
                before = f.read_bytes()
                r = subprocess.run(['python3', str(SCRIPT), str(f)], capture_output=True, text=True)
                self.assertEqual(r.returncode, code)
                self.assertLess(len(r.stdout+r.stderr), 2048)
                self.assertNotIn('secret invalid', r.stdout+r.stderr)
                self.assertEqual(f.read_bytes(), before)
                self.assertEqual([x.name for x in Path(d).iterdir()], ['evidence.json'])

if __name__ == '__main__':
    unittest.main(verbosity=2)
